-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Follows verified walking geometry and tracks arrival within the active corridor.

local Constants = APR.NavigationConstants.Navigation

local nav = APR.navigation
local Shared = APR.navigation._helpers
local CopyLocation = Shared.CopyLocation
local Distance = Shared.Distance
local HasWalkingPath = Shared.HasWalkingPath
local Now = Shared.Now
local Position = Shared.Position
local ReadableLocationValue = Shared.ReadableLocationValue
local SameAccess = Shared.SameAccess
local SameLocationFields = Shared.SameLocationFields
local SpatialDistance = Shared.SpatialDistance
local TargetMapReached = Shared.TargetMapReached
local WalkingProvider = Shared.WalkingProvider

-- Geometry belongs to the published segment; only the small cursor is mutable.
-- Cache the fixed tail once, so the arrow's movement loop measures one edge.
function nav:GetRemainingWalkYards()
    local step, position = self:GetActiveStep(), Position()
    if not HasWalkingPath(step) then return step and Distance(position, step.to) or 0 end
    if not step.pathTailYards then
        local tail = { [#step.path] = 0 }
        for index = #step.path - 1, 1, -1 do
            tail[index] = tail[index + 1] + SpatialDistance(step.path[index], step.path[index + 1])
        end
        step.pathTailYards = tail
    end
    local cursor = step.pathAimIndex or step.pathCursor or 2
    if step.pathAimPoint then
        return SpatialDistance(position, step.pathAimPoint)
            + SpatialDistance(step.pathAimPoint, step.path[cursor])
            + step.pathTailYards[cursor]
    end
    return SpatialDistance(position, step.path[cursor]) + step.pathTailYards[cursor]
end--[[APR_DIAG]]; nav.GetRemainingWalkYards = APRTrace("APR-Core/features/navigation/controller/NavigationWalking.lua:26:nav:GetRemainingWalkYards#1", nav.GetRemainingWalkYards)--[[/APR_DIAG]]

local function WalkingTerrainHeight(position, provider)
    if provider and provider.GetGuidanceHeight then
        local height = provider:GetGuidanceHeight(position)
        if type(height) == "number" and ReadableLocationValue(height) then return height end
    end
end--[[APR_DIAG]]; WalkingTerrainHeight = APRTrace("APR-Core/features/navigation/controller/NavigationWalking.lua:45:WalkingTerrainHeight#2", WalkingTerrainHeight)--[[/APR_DIAG]]

local function WalkingPosition(position, provider, step)
    if position and position.z == nil then
        if position.indoors == nil and IsIndoors then
            position = CopyLocation(position)
            position.indoors = IsIndoors() == true
        end
        local height = WalkingTerrainHeight(position, provider)
        if height == nil and provider and provider.GetWalkingCorridorHeight then
            height = provider:GetWalkingCorridorHeight(position, step)
        end
        if height ~= nil then
            position = CopyLocation(position)
            position.z = height
        end
    end
    return position
end--[[APR_DIAG]]; WalkingPosition = APRTrace("APR-Core/features/navigation/controller/NavigationWalking.lua:52:WalkingPosition#3", WalkingPosition)--[[/APR_DIAG]]

function nav:ObserveWalkingPosition(position, provider)
    local observation = self.walkingObservation
    if self.worldLoading or not (position and provider and provider.GetWalkingObservationHeight) then
        self.walkingObservation = nil
        return position
    end
    local now, indoors = Now(), position.indoors
    if indoors == nil and IsIndoors then indoors = IsIndoors() == true end
    if indoors == nil then
        self.walkingObservation = nil
        return position
    end
    local previous, moved
    if
        indoors
        and observation
        and (position.indoors == nil or observation.indoors == indoors)
        and observation.geometry == APR.navigationGeometryRevision
        and now - observation.time <= Constants.WALK_OBSERVATION_IDLE
        and SameAccess(position, observation.position)
    then
        local distance = Distance(position, observation.position)
        if
            (distance == 0 and indoors == observation.indoors)
            or (
                distance > 0
                and distance <= Constants.WALK_OBSERVATION_DISTANCE
                and now - observation.sample <= Constants.WALK_OBSERVATION_GAP
            )
        then
            previous, moved = observation.position, distance > 0
        end
    end
    local height = position.z
    if height == nil then
        if previous and not moved then
            height = previous.z
        else
            local probe = position
            if position.indoors == nil then
                probe = CopyLocation(position)
                probe.indoors = indoors
            end
            height = provider:GetWalkingObservationHeight(probe, previous)
        end
    end
    if height == nil then
        self.walkingObservation = nil
        return position
    end
    local observed = CopyLocation(position)
    observed.z = height
    -- Stationary samples do not renew evidence at an ambiguous XY.
    self.walkingObservation = {
        position = observed,
        indoors = indoors,
        geometry = APR.navigationGeometryRevision,
        time = previous and not moved and position.z == nil and observation.time or now,
        sample = now,
    }
    return observed
end--[[APR_DIAG]]; nav.ObserveWalkingPosition = APRTrace("APR-Core/features/navigation/controller/NavigationWalking.lua:70:nav:ObserveWalkingPosition#4", nav.ObserveWalkingPosition)--[[/APR_DIAG]]

local function WalkingAccessReached(position, point, checkHeight, provider)
    if not position or not point or position.instanceID ~= point.instanceID then return false end
    if checkHeight ~= false and point.z ~= nil and (position.z == nil or math.abs(position.z - point.z) > 5) then
        return false
    end
    local data = APR.NavigationData
    if
        not TargetMapReached(position, point)
        and not (
            data
            and data.IsSameAccessRegion
            and provider
            and provider.RequiresWalkingProof
            and provider:RequiresWalkingProof(position, point)
        )
    then
        return false
    end
    if data and data.IsSameAccessRegion then return data:IsSameAccessRegion(position, point) == true end
    return (point.floor == nil or position.floor == point.floor)
        and (point.accessKey == nil or position.accessKey == point.accessKey)
end--[[APR_DIAG]]; WalkingAccessReached = APRTrace("APR-Core/features/navigation/controller/NavigationWalking.lua:122:WalkingAccessReached#5", WalkingAccessReached)--[[/APR_DIAG]]

local function WalkingPointReached(position, point, provider, radius)
    if
        Distance(position, point) > (radius or Constants.WALK_ARRIVAL_RADIUS)
        or not WalkingAccessReached(position, point, not point.sharedFloorChord, provider)
    then
        return false
    end
    if provider and provider.CanFollowWalkingSegment then
        return provider:CanFollowWalkingSegment(position, point, true) == true
    end
    return true
end--[[APR_DIAG]]; WalkingPointReached = APRTrace("APR-Core/features/navigation/controller/NavigationWalking.lua:146:WalkingPointReached#6", WalkingPointReached)--[[/APR_DIAG]]

local function WalkingProjection(position, from, to)
    local dx, dy = to.x - from.x, to.y - from.y
    local lengthSquared = dx * dx + dy * dy
    local fraction = lengthSquared > 0 and ((position.x - from.x) * dx + (position.y - from.y) * dy) / lengthSquared
        or 0
    fraction = math.max(0, math.min(fraction, 1))
    local x, y = from.x + fraction * dx, from.y + fraction * dy
    return fraction, (position.x - x) ^ 2 + (position.y - y) ^ 2
end--[[APR_DIAG]]; WalkingProjection = APRTrace("APR-Core/features/navigation/controller/NavigationWalking.lua:159:WalkingProjection#7", WalkingProjection)--[[/APR_DIAG]]

local function FollowingManualCrossing(step, position)
    -- Catalogued corridors and lifts remain valid while the player is between
    -- access regions. Only the normal arrival checks can advance the cursor.
    if
        not step
        or not step.from
        or not step.to
        or not position
        or not step.departureSeen
        or not step.arrivalRadius
        or position.instanceID ~= step.from.instanceID
        or position.instanceID ~= step.to.instanceID
    then
        return false
    end
    local _, offset = WalkingProjection(position, step.from, step.to)
    if step.kind == "tram" then
        return offset <= 100 ^ 2
    elseif step.kind == "elevator" then
        local z, fromZ, toZ = position.z, step.from.z, step.to.z
        local tolerance = step.arrivalZTolerance
        return offset <= step.arrivalRadius ^ 2
            and (
                z == nil
                or (
                    fromZ ~= nil
                    and toZ ~= nil
                    and tolerance ~= nil
                    and z >= math.min(fromZ, toZ) - tolerance
                    and z <= math.max(fromZ, toZ) + tolerance
                )
            )
    elseif step.kind == "passage" and offset <= step.arrivalRadius ^ 2 then
        local data = APR.NavigationData
        return data
            and data.IsSameAccessRegion
            and (data:IsSameAccessRegion(position, step.from) or data:IsSameAccessRegion(position, step.to))
    end
    return false
end--[[APR_DIAG]]; FollowingManualCrossing = APRTrace("APR-Core/features/navigation/controller/NavigationWalking.lua:169:FollowingManualCrossing#8", FollowingManualCrossing)--[[/APR_DIAG]]

local function WalkingPointPassed(position, previous, point, following, provider)
    -- Only the adjacent outgoing edge can release a missed turn. No nearest
    -- point search across other parts of a switchback or a different floor.
    if point.mandatory or not provider or not provider.CanFollowWalkingSegment or not following then return false end
    if
        not WalkingAccessReached(position, point, false, provider)
        or not WalkingAccessReached(position, following, false, provider)
    then
        return false
    end
    local fraction, offSquared = WalkingProjection(position, point, following)
    if fraction <= 0 or offSquared > Constants.WALK_POINT_RADIUS ^ 2 then return false end
    local _, incomingSquared = WalkingProjection(position, previous, point)
    -- Stay on the incoming edge at hairpins/intersections until the outgoing
    -- edge is clearly closer. Nearby parallel ground is not forward progress.
    if math.sqrt(offSquared) + 1 >= math.sqrt(incomingSquared) then return false end
    local projection = CopyLocation(following)
    projection.x, projection.y =
        point.x + fraction * (following.x - point.x), point.y + fraction * (following.y - point.y)
    projection.z = point.z and following.z and point.z + fraction * (following.z - point.z) or nil
    projection.geometryVerified = point.geometryVerified and following.geometryVerified
    -- Smoothed edges can cross a hill between vertices of equal height. Prefer
    -- the actual unique surface here; interpolation is only for stacked cells.
    projection.z = WalkingTerrainHeight(projection, provider) or projection.z
    if not WalkingAccessReached(position, projection, nil, provider) then return false end
    -- Prove the route edge and the player's forward connection to it. A
    -- directed descent may be walkable even when the old turn cannot be reached.
    return provider:CanFollowWalkingSegment(point, following) == true
        and provider:CanFollowWalkingSegment(position, projection, true) == true
        and provider:CanFollowWalkingSegment(position, following, true) == true
end--[[APR_DIAG]]; WalkingPointPassed = APRTrace("APR-Core/features/navigation/controller/NavigationWalking.lua:210:WalkingPointPassed#9", WalkingPointPassed)--[[/APR_DIAG]]

local function WalkingDestinationReached(step, position, provider)
    if not HasWalkingPath(step) or Distance(position, step.to) > 1 then return false end
    local endpoint = step.path[#step.path]
    -- A precise observed destination can supersede old bends after another
    -- journey. A broad interaction range or unknown stacked height cannot.
    if endpoint.z == nil and endpoint.floor == nil then return false end
    for index = step.pathCursor or 2, #step.path - 1 do
        if step.path[index].mandatory then return false end
    end
    return WalkingPointReached(position, endpoint, provider)
end--[[APR_DIAG]]; WalkingDestinationReached = APRTrace("APR-Core/features/navigation/controller/NavigationWalking.lua:242:WalkingDestinationReached#10", WalkingDestinationReached)--[[/APR_DIAG]]

local function ProveOutdoorAim(position, from, to, fraction, provider)
    local point = CopyLocation(to)
    point.x, point.y = from.x + fraction * (to.x - from.x), from.y + fraction * (to.y - from.y)
    point.z = WalkingTerrainHeight(point, provider) or (from.z + fraction * (to.z - from.z))
    point.geometryVerified = from.geometryVerified and to.geometryVerified
    if Distance(position, point) <= Constants.WALK_OUTDOOR_JOIN_DISTANCE
        and provider:CanFollowWalkingSegment(position, point, "outdoor") == true then
        return point
    end
end--[[APR_DIAG]]; ProveOutdoorAim = APRTrace("APR-Core/features/navigation/controller/NavigationWalking.lua:266:ProveOutdoorAim#14", ProveOutdoorAim)--[[/APR_DIAG]]

local function FollowOutdoorPath(step, position, provider, cursor, limit)
    if
        not (
            position
            and not position.isInstance
            and not position.floor
            and not position.accessKey
            and position.indoors ~= true
            and IsIndoors
            and IsIndoors() == false
            and provider
            and provider.CanFollowWalkingSegment
        )
    then
        step.walkingFollow = nil
        return
    end
    local cached = step.walkingFollow
    if
        cached
        and (cached.aim or position.z == nil)
        and cached.cursor == cursor
        and cached.geometry == APR.navigationGeometryRevision
        and SameLocationFields(position, cached.position, Constants.LOCATION_FIELDS)
    then
        return cached.aim and cursor or nil, cached.aim, cached.aimPoint
    end

    local path = step.path
    -- A late result or a missed poll can leave the player well ahead of the
    -- cursor. Extend the scan by that displacement within the existing bounds.
    local window = Constants.WALK_OUTDOOR_RECOVERY_DISTANCE
        + math.min(Constants.WALK_OUTDOOR_JOIN_DISTANCE, Distance(position, path[cursor - 1]))
    local best, bestDistance, remainingOnEdge, along = cursor, math.huge, 0, 0
    for index = cursor, limit do
        local from, to = path[index - 1], path[index]
        if
            not WalkingAccessReached(position, from, false, provider)
            or not WalkingAccessReached(position, to, false, provider)
            or to.indoors == true
        then
            break
        end
        local length = Distance(from, to)
        local dz = from.z and to.z and to.z - from.z
        if dz == nil or math.abs(dz) > math.max(5, length) then break end
        local fraction, squared = WalkingProjection(position, from, to)
        local distance = math.sqrt(squared)
        local margin = index == best + 1 and 0 or 4
        if
            (position.z == nil or math.abs(position.z - (from.z + dz * fraction)) <= 5)
            and (
                distance + margin < bestDistance or (margin == 0 and distance == bestDistance and remainingOnEdge == 0)
            )
        then
            best, bestDistance, remainingOnEdge = index, distance, length * (1 - fraction)
        end
        along = along + length
        if to.mandatory or along > window then break end
    end

    local aim, aimPoint
    if position.z ~= nil and bestDistance <= Constants.WALK_OUTDOOR_JOIN_DISTANCE then
        local farthest, ahead = best, remainingOnEdge
        local aimEdge = ahead > Constants.WALK_LOOK_AHEAD and best or nil
        while not aimEdge and farthest < limit and not path[farthest].mandatory do
            local from, to = path[farthest], path[farthest + 1]
            if not WalkingAccessReached(position, to, false, provider) or to.indoors == true then break end
            local length = Distance(from, to)
            if to.z == nil or math.abs(to.z - from.z) > math.max(5, length) then break end
            local previous = path[farthest - 1]
            local direction = (from.x - previous.x) * (to.x - from.x)
                + (from.y - previous.y) * (to.y - from.y)
            -- Stop the wide search at a reversal. A nearby turn can still
            -- be joined directly, including an off-centre departure.
            if direction < 0 and (farthest > best or remainingOnEdge > Constants.WALK_POINT_RADIUS) then break end
            ahead = ahead + length
            if ahead > Constants.WALK_LOOK_AHEAD then
                if direction > 0 then aimEdge = farthest + 1 end
                break
            end
            farthest = farthest + 1
        end
        if aimEdge then
            -- A fixed look-ahead distance keeps the bearing stable as the
            -- player approaches and passes vertices of different spacing.
            local from, to = path[aimEdge - 1], path[aimEdge]
            local fraction = 1 - (ahead - Constants.WALK_LOOK_AHEAD) / Distance(from, to)
            aimPoint = ProveOutdoorAim(position, from, to, fraction, provider)
            if aimPoint then aim = aimEdge end
        end
        -- Sample the remote part of the window and check every nearby bend.
        -- A wide stride must not skip the only clear vertex near the player.
        local nearby = math.min(farthest, best + 4)
        local stride = math.max(1, math.ceil((farthest - nearby) / 6))
        local index = farthest
        while not aim and index > best do
            if
                Distance(position, path[index]) <= Constants.WALK_OUTDOOR_JOIN_DISTANCE
                and provider:CanFollowWalkingSegment(position, path[index], "outdoor") == true
            then
                aim = index
                break
            end
            index = index > nearby and math.max(nearby, index - stride) or index - 1
        end
        if not aim and not path[best].mandatory and best < #path
            and Distance(position, path[best]) <= Constants.WALK_POINT_RADIUS then
            -- The nearest vertex can be behind the player even though a short
            -- part of the outgoing edge is clear. Check that edge before the bend.
            for edge = math.min(farthest, best + 1), best, -1 do
                local from, to = path[edge - 1], path[edge]
                local fraction, offset = WalkingProjection(position, from, to)
                if offset <= Constants.WALK_POINT_RADIUS ^ 2 then
                    local length = Distance(from, to)
                    local advance = 1 - fraction
                    for _ = 1, 3 do
                        advance = advance / 2
                        if length * advance < 0.25 then break end
                        aimPoint = ProveOutdoorAim(position, from, to, fraction + advance, provider)
                        if aimPoint then
                            aim = edge
                            break
                        end
                    end
                end
                if aim then break end
            end
        end
        if not aim and Distance(position, path[best]) <= Constants.WALK_OUTDOOR_JOIN_DISTANCE
            and provider:CanFollowWalkingSegment(position, path[best], "outdoor") == true then
            aim = best
        end
    end
    local nextCursor = aim and best or cursor
    step.walkingFollow = {
        position = position,
        cursor = nextCursor,
        geometry = APR.navigationGeometryRevision,
        aim = aim,
        aimPoint = aimPoint,
        off = bestDistance,
        missed = best > cursor,
    }
    return aim and nextCursor or nil, aim, aimPoint
end--[[APR_DIAG]]; FollowOutdoorPath = APRTrace("APR-Core/features/navigation/controller/NavigationWalking.lua:254:FollowOutdoorPath#11", FollowOutdoorPath)--[[/APR_DIAG]]

function nav:AdvanceWalkingPath(step, position, provider, beforePublication)
    if not HasWalkingPath(step) then return true, true end
    if step.path.flight then
        if not position or position.instanceID ~= step.from.instanceID then return false, false end
        local path, cursor = step.path, step.pathCursor or 2
        while cursor < #path do
            local _, offset = WalkingProjection(position, path[cursor], path[cursor + 1])
            if Distance(position, path[cursor]) > 20 and offset > 20 ^ 2 then break end
            cursor = cursor + 1
        end
        if cursor ~= step.pathCursor then
            step.pathCursor = cursor
            if not beforePublication then self:Notify() end
        end
        local _, offset = WalkingProjection(position, path[cursor - 1], path[cursor])
        return cursor == #path, offset <= Constants.MOVEMENT_REPLAN_YARDS ^ 2
    end
    provider = provider or WalkingProvider()
    local endpoint = step.path[#step.path]
    if endpoint.sharedFloorChord then
        position = WalkingPosition(position, provider, step)
        if not position or not provider or not provider.CanFollowWalkingSegment then return false, false end
        if beforePublication then
            return false, provider:CanFollowWalkingSegment(position, endpoint, true) == true
        end
        return WalkingPointReached(position, endpoint, provider)
    end
    local atStart
    if beforePublication then
        if not position then return false, false end
        local start = step.path[1]
        atStart = Distance(position, start) == 0
            and (not position.z or not start.z or math.abs(position.z - start.z) <= 5)
        if not provider or not provider.CanFollowWalkingSegment or (atStart and (
            #step.path < 3 or step.path[2].mandatory or Distance(position, step.path[2]) > Constants.WALK_POINT_RADIUS
        )) then
            return false, true
        end
    end
    position = WalkingPosition(position, provider, step)
    local current = step.pathCursor or 2
    local cursor = current
    -- Dense duplicate points cannot monopolize an arrival poll.
    local limit = math.min(cursor + 64, #step.path)
    local projected, aim, aimPoint = FollowOutdoorPath(step, position, provider, cursor, limit)
    cursor = projected or cursor
    while not aim and not atStart and cursor < limit do
        local previous, point, following = step.path[cursor - 1], step.path[cursor], step.path[cursor + 1]
        local radius = not point.mandatory
                and provider
                and provider.CanFollowWalkingSegment
                and Constants.WALK_POINT_RADIUS
            or Constants.WALK_ARRIVAL_RADIUS
        if
            (
                WalkingPointReached(position, point, provider, radius)
                and (
                    not provider
                    or not provider.CanFollowWalkingSegment
                    or provider:CanFollowWalkingSegment(position, following, true) == true
                )
            ) or WalkingPointPassed(position, previous, point, following, provider)
        then
            cursor = cursor + 1
        else
            -- A late sample can land on a later edge without entering the
            -- radii of the intervening bends. Follow the ordered corridor,
            -- checking each skipped edge and stopping at mandatory points.
            if not position or position.z == nil or not provider or not provider.CanFollowWalkingSegment then break end
            local _, approachSquared = WalkingProjection(position, previous, point)
            if approachSquared <= Constants.WALK_POINT_RADIUS ^ 2 then break end
            local recovered, along = nil, 0
            for index = cursor + 1, limit - 1 do
                local skipped, bend = step.path[index - 1], step.path[index]
                along = along + Distance(skipped, bend)
                if
                    along > Constants.WALK_RECOVERY_DISTANCE
                    or skipped.mandatory
                    or bend.mandatory
                    or not WalkingAccessReached(position, skipped, false, provider)
                    or not WalkingAccessReached(bend, skipped, false, provider)
                    or provider:CanFollowWalkingSegment(skipped, bend) ~= true
                then
                    break
                end
                if WalkingPointPassed(position, skipped, bend, step.path[index + 1], provider) then
                    recovered = index + 1
                    break
                end
            end
            if not recovered then break end
            cursor = recovered
        end
    end
    local aimIndex = aim and aim > cursor and aim or nil
    local follow = step.walkingFollow
    -- An XY match can retire a stale bearing, but only a proven walking
    -- connection can move the cursor or publish a replacement target.
    local target = step.path[cursor]
    local unavailable = not aim and cursor == current and follow and not target.mandatory
        and (step.pathArrowUnavailable or (follow.missed and follow.off <= Constants.WALK_POINT_RADIUS
            and Distance(position, target) > Constants.WALK_POINT_RADIUS))
        and (position.z == nil or Distance(position, target) > Constants.WALK_OUTDOOR_JOIN_DISTANCE
            or provider:CanFollowWalkingSegment(position, target, "outdoor") ~= true)
        or nil
    if cursor ~= step.pathCursor or aimIndex ~= step.pathAimIndex or aimPoint ~= step.pathAimPoint
        or unavailable ~= step.pathArrowUnavailable then
        step.pathCursor, step.pathAimIndex, step.pathAimPoint = cursor, aimIndex, aimPoint
        step.pathArrowUnavailable = unavailable
        if not beforePublication then self:Notify() end
    end
    if beforePublication then
        return cursor >= #step.path,
            aim ~= nil or (not unavailable and (atStart or provider:CanFollowWalkingSegment(position, target, true) == true))
    end
    return cursor >= #step.path
end--[[APR_DIAG]]; nav.AdvanceWalkingPath = APRTrace("APR-Core/features/navigation/controller/NavigationWalking.lua:378:nav:AdvanceWalkingPath#12", nav.AdvanceWalkingPath)--[[/APR_DIAG]]

local function ReuseWalkingCursor(step, previous)
    if not HasWalkingPath(step) or not HasWalkingPath(previous) then return end
    local cursor = previous.pathCursor or 2
    for index = cursor - 1, cursor do
        local a, b = step.path[index], previous.path[index]
        if not a or not b or a.instanceID ~= b.instanceID or a.x ~= b.x or a.y ~= b.y or a.z ~= b.z then return end
    end
    step.pathCursor = cursor
end--[[APR_DIAG]]; ReuseWalkingCursor = APRTrace("APR-Core/features/navigation/controller/NavigationWalking.lua:464:ReuseWalkingCursor#13", ReuseWalkingCursor)--[[/APR_DIAG]]

