APR.navigation._helpers.WalkingPointReached = WalkingPointReached
APR.navigation._helpers.WalkingDestinationReached = WalkingDestinationReached
APR.navigation._helpers.WalkingProjection = WalkingProjection
APR.navigation._helpers.WalkingPosition = WalkingPosition
APR.navigation._helpers.FollowingManualCrossing = FollowingManualCrossing
APR.navigation._helpers.ReuseWalkingCursor = ReuseWalkingCursor
